# Generated by android-repo-setup bootstrap.
$ErrorActionPreference = 'Stop'
$root = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'))
$pin = 'v0.1.20'
$config = Get-Content (Join-Path $root '.project/setup/config.yaml') -Raw
if ($config -notmatch '(?m)^tooling_ref: [''"]?([^''" #\r\n]+)[''"]? *\r?$' -or $Matches[1] -cne $pin) { throw 'tooling_ref changed; regenerate bootstrap with the pinned CLI' }
$cache = Join-Path $PSScriptRoot 'cache'
$destination = Join-Path $cache $pin
$exe = Join-Path $destination 'bin/android-repo-setup.exe'
foreach ($path in @((Join-Path $root '.project'), $PSScriptRoot, $cache, $destination, (Join-Path $destination 'bin'), $exe)) {
  if ((Test-Path -LiteralPath $path) -and ((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Refusing symlink: $path" }
}
if (!(Test-Path -LiteralPath $exe)) {
  New-Item -ItemType Directory -Force $cache | Out-Null
  $stage = Join-Path $cache ('.install.' + [Guid]::NewGuid().ToString('N'))
  New-Item -ItemType Directory $stage | Out-Null
  try {
    if ($pin.StartsWith('v')) {
      if ([Environment]::Is64BitOperatingSystem -eq $false -or $env:PROCESSOR_ARCHITECTURE -ne 'AMD64') { throw 'No release binary for this platform. Install Rust and use a full commit SHA tooling_ref for a cached source build.' }
      $archive = 'android-repo-setup-x86_64-pc-windows-msvc.zip'
      $url = "https://github.com/lambdawalker/gradle.android-repo-setup/releases/download/$pin/$archive"
      Invoke-WebRequest -UseBasicParsing $url -OutFile (Join-Path $stage $archive)
      Invoke-WebRequest -UseBasicParsing "$url.sha256" -OutFile (Join-Path $stage 'checksum')
      $hash = ((Get-Content (Join-Path $stage 'checksum') -Raw).Trim() -split '\s+')[0]
      if ($hash -notmatch '^[0-9a-fA-F]{64}$' -or (Get-FileHash (Join-Path $stage $archive) -Algorithm SHA256).Hash -ine $hash) { throw 'SHA256 checksum mismatch' }
      Expand-Archive (Join-Path $stage $archive) (Join-Path $stage 'bin')
    } else {
      $previousTarget = $env:CARGO_TARGET_DIR
      try {
        $env:CARGO_TARGET_DIR = Join-Path $stage 'target'
        & cargo install --locked --root $stage --git https://github.com/lambdawalker/gradle.android-repo-setup.git --rev $pin android-repo-setup
        if ($LASTEXITCODE -ne 0) { throw 'Cargo installation failed' }
      } finally { $env:CARGO_TARGET_DIR = $previousTarget }
    }
    $version = & (Join-Path $stage 'bin/android-repo-setup.exe') --version
    if ($LASTEXITCODE -ne 0 -or ($pin.StartsWith('v') -and $version -cne "android-repo-setup $($pin.Substring(1))") -or $version -notmatch '^android-repo-setup ') { throw 'Downloaded CLI version mismatch' }
    Remove-Item (Join-Path $stage 'target') -Recurse -Force -ErrorAction SilentlyContinue
    if (Test-Path $destination) { throw 'Invalid existing cache; remove it and retry' }
    Move-Item $stage $destination
  } finally { if (Test-Path $stage) { Remove-Item $stage -Recurse -Force } }
}
$version = & $exe --version
if ($LASTEXITCODE -ne 0 -or ($pin.StartsWith('v') -and $version -cne "android-repo-setup $($pin.Substring(1))")) { throw 'Cached CLI version mismatch' }
$env:PATH = (Split-Path -Parent $exe) + [IO.Path]::PathSeparator + $env:PATH
& $exe --project $root @args
exit $LASTEXITCODE
